def get_current_weather(city, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0208000" if __import__("os").path.isdir("./environment_mix/0208000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso_z(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _norm_city(c):
        c = c.strip()
        c = re.sub(r"\s+", " ", c)
        # Title-case for English city names; keep hyphen/apostrophe reasonably
        return c.title()

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(1000, 9999)}"

    def _transition_ok(cur, nxt, transitions):
        return nxt in transitions.get(cur, [])

    def _pick_active_client(clients):
        for c in clients:
            if c.get("status") == "active":
                return c
        return None

    def _append_invocation(invocations, row):
        invocations.append(row)

    def _enforce_limits(client, invocations, now):
        client_id = client.get("id")
        rl = client.get("rate_limit_per_minute")
        dq = client.get("daily_quota")

        if not isinstance(rl, int) or not (1 <= rl <= 6000):
            return ("UNAUTHORIZED", "Client rate limit misconfigured", "CLIENT_MISCONFIGURED")
        if not isinstance(dq, int) or not (1 <= dq <= 1000000):
            return ("UNAUTHORIZED", "Client daily quota misconfigured", "CLIENT_MISCONFIGURED")

        window_start = now - datetime.timedelta(seconds=60)
        count_60s = 0
        for r in invocations:
            if r.get("client_id") != client_id:
                continue
            dt = _parse_iso_z(r.get("created_at"))
            if dt is None:
                continue
            if dt >= window_start and dt <= now:
                count_60s += 1
        if count_60s >= rl:
            return ("RATE_LIMIT", "Rate limit exceeded", "RATE_LIMITED")

        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        count_day = 0
        for r in invocations:
            if r.get("client_id") != client_id:
                continue
            dt = _parse_iso_z(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_start and dt <= now:
                count_day += 1
        if count_day >= dq:
            return ("QUOTA_EXCEEDED", "Daily quota exceeded", "DAILY_QUOTA_EXCEEDED")

        return None

    def _wmo_desc(code):
        # Minimal mapping; vendor cache is optional.
        mapping = {
            0: "Clear sky",
            1: "Mainly clear",
            2: "Partly cloudy",
            3: "Overcast",
            45: "Fog",
            48: "Rime fog",
            51: "Light drizzle",
            53: "Drizzle",
            55: "Dense drizzle",
            61: "Slight rain",
            63: "Rain",
            65: "Heavy rain",
            71: "Slight snow",
            73: "Snow",
            75: "Heavy snow",
            80: "Rain showers",
            81: "Rain showers",
            82: "Violent rain showers",
            95: "Thunderstorm",
        }
        return mapping.get(code, "Unknown conditions")

    t0 = time.time()
    now = _now_utc()

    # Load store
    api_clients = _load("api_clients.json")
    tool_invocations = _load("tool_invocations.json")
    locations = _load("locations.json")
    weather_hourly = _load("weather_hourly.json")

    # Ambient auth: find any active client that can serve
    client = _pick_active_client(api_clients)
    if not client:
        # Cannot even attribute invocation safely; return UNAUTHORIZED
        return _err("UNAUTHORIZED", "No active client available to execute tool")

    # Create invocation row (received)
    inv_id = _gen_id("inv")
    inv = {
        "id": inv_id,
        "client_id": client.get("id"),
        "tool_name": "get_current_weather",
        "city": city if isinstance(city, str) else None,
        "start_date": None,
        "end_date": None,
        "timezone_name": None,
        "resolved_location_id": None,
        "request_status": "received",
        "error_code": None,
        "error_message": None,
        "response_summary": None,
        "provider_calls": 0,
        "duration_ms": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    _append_invocation(tool_invocations, inv)
    _save("tool_invocations.json", tool_invocations)

    def _fail(api_code, public_msg, error_code=None, error_message=None):
        end = _now_utc()
        # transition to failed along valid path
        transitions = {
            "received": ["validated", "failed"],
            "validated": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        cur = inv["request_status"]
        if cur != "failed":
            if cur == "received":
                inv["request_status"] = "failed" if _transition_ok(cur, "failed", transitions) else "failed"
            elif cur == "validated":
                inv["request_status"] = "failed"
            elif cur == "running":
                inv["request_status"] = "failed"
            else:
                inv["request_status"] = "failed"
        inv["error_code"] = error_code
        inv["error_message"] = error_message or public_msg
        inv["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        inv["updated_at"] = _iso(end)
        _save("tool_invocations.json", tool_invocations)
        return _err(api_code, public_msg, error_code=error_code)

    def _succeed(summary, resolved_location_id=None):
        end = _now_utc()
        transitions = {
            "received": ["validated", "failed"],
            "validated": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        # received -> validated -> running -> succeeded
        if inv["request_status"] == "received":
            inv["request_status"] = "validated"
        if inv["request_status"] == "validated":
            inv["request_status"] = "running"
        if inv["request_status"] == "running":
            inv["request_status"] = "succeeded"
        if inv["request_status"] != "succeeded":
            inv["request_status"] = "succeeded"
        inv["resolved_location_id"] = resolved_location_id
        inv["response_summary"] = summary
        inv["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        inv["updated_at"] = _iso(end)
        _save("tool_invocations.json", tool_invocations)
        return {
            "city": inv["city"],
            "location_id": resolved_location_id,
            "summary": summary,
        }

    # Client must be active
    if client.get("status") != "active":
        return _fail("UNAUTHORIZED", "Client not permitted", error_code="CLIENT_NOT_ACTIVE")

    # Rate/quota enforcement
    lim = _enforce_limits(client, tool_invocations[:-1], now)  # exclude current received row
    if lim:
        api_code, msg, ec = lim
        return _fail(api_code, msg, error_code=ec)

    # Validate input
    if not isinstance(city, str) or not city.strip():
        return _fail("VALIDATION_ERROR", "city must be a non-empty string", error_code="INVALID_CITY")

    norm_city = _norm_city(city)
    inv["city"] = norm_city
    inv["updated_at"] = _iso(_now_utc())
    _save("tool_invocations.json", tool_invocations)

    # Resolve location: must be resolved
    candidates = [l for l in locations if isinstance(l.get("english_city_name"), str) and l.get("english_city_name") == norm_city]
    resolved = None
    for l in candidates:
        if l.get("resolution_status") == "resolved":
            resolved = l
            break
    if not resolved:
        # Cannot create here with guarantee of resolved; tool says NOT_FOUND when cannot resolve
        return _fail("NOT_FOUND", "City could not be resolved to a location", error_code="CITY_NOT_FOUND")

    loc_id = resolved.get("id")
    inv["resolved_location_id"] = loc_id
    inv["updated_at"] = _iso(_now_utc())
    _save("tool_invocations.json", tool_invocations)

    # Determine current UTC hour bucket
    hour_start = now.replace(minute=0, second=0, microsecond=0)
    hour_iso = _iso(hour_start)

    # Find cached row for this hour/provider
    provider = "open_meteo"
    row = None
    for r in weather_hourly:
        if r.get("location_id") == loc_id and r.get("hour_start_utc") == hour_iso and r.get("source_provider") == provider and r.get("ingest_status") != "superseded":
            row = r
            break

    def _is_stale(r, now_dt):
        fetched = _parse_iso_z(r.get("fetched_at"))
        if fetched is None:
            return True
        kind = r.get("data_kind")
        if kind == "observed":
            return (now_dt - fetched) > datetime.timedelta(minutes=15)
        return (now_dt - fetched) > datetime.timedelta(hours=2)

    provider_calls = 0
    if row is None or _is_stale(row, now):
        # "Fetch" from provider offline: deterministically synthesize based on location/hour
        provider_calls = 1
        seed = hash((loc_id, hour_iso, provider)) & 0xFFFFFFFF
        rnd = random.Random(seed)
        temp = round(rnd.uniform(-5.0, 32.0), 1)
        code = int(rnd.choice([0, 1, 2, 3, 45, 51, 61, 63, 65, 71, 80, 95]))
        desc = _wmo_desc(code)
        data_kind = "observed"  # current hour treated as observed

        # Supersede any existing non-superseded rows for same key
        for r in weather_hourly:
            if r.get("location_id") == loc_id and r.get("hour_start_utc") == hour_iso and r.get("source_provider") == provider and r.get("ingest_status") != "superseded":
                if r.get("id") != (row.get("id") if row else None):
                    # only supersede if distinct row
                    if r.get("ingest_status") in ("fresh", "stale"):
                        r["ingest_status"] = "superseded"
                        r["updated_at"] = _iso(_now_utc())

        if row is not None:
            # Update existing to preserve uniqueness
            row["temperature_c"] = temp
            row["weather_code"] = code
            row["weather_description"] = desc
            row["data_kind"] = data_kind
            row["ingest_status"] = "fresh"
            row["fetched_at"] = _iso(_now_utc())
            row["updated_at"] = _iso(_now_utc())
        else:
            new = {
                "id": _gen_id("wh"),
                "location_id": loc_id,
                "hour_start_utc": hour_iso,
                "temperature_c": temp,
                "weather_code": code,
                "weather_description": desc,
                "data_kind": data_kind,
                "source_provider": provider,
                "ingest_status": "fresh",
                "fetched_at": _iso(_now_utc()),
                "created_at": _iso(_now_utc()),
                "updated_at": _iso(_now_utc()),
            }
            weather_hourly.append(new)
            row = new

        _save("weather_hourly.json", weather_hourly)

    inv["provider_calls"] = int(inv.get("provider_calls") or 0) + provider_calls
    inv["updated_at"] = _iso(_now_utc())
    _save("tool_invocations.json", tool_invocations)

    summary = f"{norm_city}: {row.get('temperature_c')}°C, {row.get('weather_description') or _wmo_desc(int(row.get('weather_code') or 0))} (code {row.get('weather_code')}) @ {row.get('hour_start_utc')}"
    return _succeed(summary, resolved_location_id=loc_id)

def get_weather_by_datetime_range(city, start_date, end_date, **_extra):
    import json, os, datetime, time, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0208000" if __import__("os").path.isdir("./environment_mix/0208000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_ymd(s):
        if not isinstance(s, str):
            return None
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
            return None
        try:
            return datetime.date.fromisoformat(s)
        except ValueError:
            return None

    def _norm_city(c):
        c = c.strip()
        c = re.sub(r"\s+", " ", c)
        return c.title()

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(ts_ms):
        # 48-bit time + 80-bit randomness => 26 chars
        t = int(ts_ms)
        out = []
        for _ in range(10):
            out.append(_B32[t & 31])
            t //= 32
        out = out[::-1]
        r = random.getrandbits(80)
        for _ in range(16):
            out.append(_B32[r & 31])
            r //= 32
        return "".join(out)

    def _gen_id(prefix):
        return f"{prefix}_{_ulid_like(int(time.time() * 1000))}"

    def _inv_transition_ok(frm, to):
        allowed = {
            "received": {"validated", "failed"},
            "validated": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        return frm in allowed and to in allowed[frm]

    def _update_inv(inv, tool_invocations, status=None, **fields):
        if status is not None:
            if not _inv_transition_ok(inv.get("request_status"), status):
                return False
            inv["request_status"] = status
        for k, v in fields.items():
            inv[k] = v
        inv["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        # persist: replace by id
        for i, row in enumerate(tool_invocations):
            if row.get("id") == inv.get("id"):
                tool_invocations[i] = inv
                return True
        tool_invocations.append(inv)
        return True

    def _select_authorized_client(api_clients, tool_invocations):
        # Ambient auth: find ANY active client that is currently under rate/quota.
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now_dt - datetime.timedelta(seconds=60)
        utc_day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

        # Pre-parse timestamps once
        def _parse_dt(s):
            if not isinstance(s, str):
                return None
            try:
                s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
                dt = datetime.datetime.fromisoformat(s2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None

        # Build per-client counters from existing tool_invocations
        per_client_last_minute = {}
        per_client_today = {}
        for inv in tool_invocations:
            cid = inv.get("client_id")
            dt = _parse_dt(inv.get("created_at"))
            if cid and dt:
                if dt >= one_min_ago:
                    per_client_last_minute[cid] = per_client_last_minute.get(cid, 0) + 1
                if dt >= utc_day_start and dt <= now_dt:
                    per_client_today[cid] = per_client_today.get(cid, 0) + 1

        active_clients = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
        # Prefer clients that can accept at least one more call right now.
        for c in active_clients:
            cid = c.get("id")
            rl = c.get("rate_limit_per_minute")
            dq = c.get("daily_quota")
            if not cid or not isinstance(rl, int) or not isinstance(dq, int):
                continue
            if per_client_last_minute.get(cid, 0) < rl and per_client_today.get(cid, 0) < dq:
                return c
        # If none are currently within limits, but there exists an active client, caller is "authorized"
        # yet must be rate/ quota limited (choose any active to log against).
        if active_clients:
            return active_clients[0]
        return None

    def _enforce_limits(client, tool_invocations):
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now_dt - datetime.timedelta(seconds=60)
        utc_day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

        def _parse_dt(s):
            if not isinstance(s, str):
                return None
            try:
                s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
                dt = datetime.datetime.fromisoformat(s2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None

        cid = client.get("id")
        rl = client.get("rate_limit_per_minute")
        dq = client.get("daily_quota")
        if not isinstance(rl, int) or not isinstance(dq, int):
            return ("VALIDATION_ERROR", "Client limits misconfigured.", "CLIENT_LIMITS_INVALID")

        last_minute = 0
        today = 0
        for inv in tool_invocations:
            if inv.get("client_id") != cid:
                continue
            dt = _parse_dt(inv.get("created_at"))
            if not dt:
                continue
            if dt >= one_min_ago:
                last_minute += 1
            if dt >= utc_day_start and dt <= now_dt:
                today += 1

        if last_minute >= rl:
            return ("RATE_LIMIT", f"Rate limit exceeded for client (limit={rl}/min).", "RATE_LIMITED")
        if today >= dq:
            return ("QUOTA_EXCEEDED", f"Daily quota exceeded for client (quota={dq}/day).", "DAILY_QUOTA_EXCEEDED")
        return None

    def _find_or_create_resolved_location(norm_city, locations):
        # Prefer an already-resolved row for the city (provider open_meteo preferred).
        candidates = [r for r in locations if isinstance(r, dict) and r.get("english_city_name") == norm_city]
        resolved = [r for r in candidates if r.get("resolution_status") == "resolved"]
        if resolved:
            for r in resolved:
                if r.get("provider") == "open_meteo":
                    return r, False
            return resolved[0], False

        # Create a resolved location placeholder if none resolved exists.
        # For offline server, we cannot geocode: use a deterministic-ish but valid lat/lon (0,0) and UTC.
        ts = _iso(datetime.datetime.now(datetime.timezone.utc))
        new_row = {
            "id": _gen_id("wcs_loc"),
            "english_city_name": norm_city,
            "country_code": None,
            "admin_region": None,
            "latitude": 0.0,
            "longitude": 0.0,
            "timezone_name": "UTC",
            "resolution_status": "resolved",
            "provider": "open_meteo",
            "provider_location_ref": None,
            "created_at": ts,
            "updated_at": ts,
        }
        locations.append(new_row)
        return new_row, True

    def _hourly_bounds(start_d, end_d):
        start_dt = datetime.datetime(start_d.year, start_d.month, start_d.day, 0, 0, 0, tzinfo=datetime.timezone.utc)
        end_excl = datetime.datetime(end_d.year, end_d.month, end_d.day, 0, 0, 0, tzinfo=datetime.timezone.utc) + datetime.timedelta(days=1)
        return start_dt, end_excl

    def _parse_hour(s):
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _weather_desc(code):
        # Minimal mapping for human readability
        if code == 0:
            return "Clear sky"
        if 1 <= code <= 3:
            return "Mainly clear"
        if code in (45, 48):
            return "Fog"
        if code in (51, 53, 55):
            return "Drizzle"
        if code in (61, 63, 65):
            return "Rain"
        if code in (80, 81, 82):
            return "Rain showers"
        if code in (95, 96, 99):
            return "Thunderstorm"
        return None

    def _is_stale(row, as_of):
        fetched = _parse_hour(row.get("fetched_at"))
        if not fetched:
            return True
        kind = row.get("data_kind")
        age = as_of - fetched
        if kind == "observed":
            return age > datetime.timedelta(minutes=15)
        return age > datetime.timedelta(hours=2)

    def _ensure_hour(location_id, hour_start_utc, weather_hourly):
        # Ensure there is a fresh datapoint for (location_id, hour_start_utc, source_provider='open_meteo')
        # If stale/missing, upsert and supersede previous as needed.
        provider = "open_meteo"
        existing = None
        for r in weather_hourly:
            if not isinstance(r, dict):
                continue
            if r.get("location_id") == location_id and r.get("source_provider") == provider:
                dt = _parse_hour(r.get("hour_start_utc"))
                if dt and dt == hour_start_utc:
                    existing = r
                    break

        as_of = datetime.datetime.now(datetime.timezone.utc)
        if existing and existing.get("ingest_status") in ("fresh", "stale") and not _is_stale(existing, as_of):
            return existing, 0, False

        # Determine observed vs forecast by comparing to current UTC hour bucket
        curr_hour = as_of.replace(minute=0, second=0, microsecond=0)
        data_kind = "observed" if hour_start_utc <= curr_hour else "forecast"

        # Supersede prior versions for same key (if any)
        changed = False
        if existing:
            # overwrite in place while preserving uniqueness; do not create new row
            ts = _iso(as_of)
            # generate deterministic but plausible values
            seed = (hash(location_id) ^ int(hour_start_utc.timestamp() // 3600)) & 0xFFFFFFFF
            rnd = random.Random(seed)
            temp = max(-100.0, min(70.0, rnd.uniform(-5.0, 30.0)))
            code = rnd.randint(0, 99)
            existing.update({
                "temperature_c": float(temp),
                "weather_code": int(code),
                "weather_description": _weather_desc(int(code)),
                "data_kind": data_kind,
                "source_provider": provider,
                "ingest_status": "fresh",
                "fetched_at": ts,
                "updated_at": ts,
            })
            changed = True
            return existing, 1, changed

        # No existing row for key: create new
        ts = _iso(as_of)
        seed = (hash(location_id) ^ int(hour_start_utc.timestamp() // 3600)) & 0xFFFFFFFF
        rnd = random.Random(seed)
        temp = max(-100.0, min(70.0, rnd.uniform(-5.0, 30.0)))
        code = rnd.randint(0, 99)
        new_row = {
            "id": _gen_id("wcs_whr"),
            "location_id": location_id,
            "hour_start_utc": _iso(hour_start_utc),
            "temperature_c": float(temp),
            "weather_code": int(code),
            "weather_description": _weather_desc(int(code)),
            "data_kind": data_kind,
            "source_provider": provider,
            "ingest_status": "fresh",
            "fetched_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        weather_hourly.append(new_row)
        return new_row, 1, True

    # Load datastore
    api_clients = _load("api_clients.json")
    locations = _load("locations.json")
    weather_hourly = _load("weather_hourly.json")
    tool_invocations = _load("tool_invocations.json")

    if not isinstance(api_clients, list): api_clients = []
    if not isinstance(locations, list): locations = []
    if not isinstance(weather_hourly, list): weather_hourly = []
    if not isinstance(tool_invocations, list): tool_invocations = []

    client = _select_authorized_client(api_clients, tool_invocations)
    if not client:
        # Cannot even attribute the invocation: no active clients in store
        return _err("UNAUTHORIZED", "No active API client available to serve this request.")

    # Create invocation row immediately (received)
    created_ts = _iso(datetime.datetime.now(datetime.timezone.utc))
    inv = {
        "id": _gen_id("wcs_inv"),
        "client_id": client.get("id"),
        "tool_name": "get_weather_by_datetime_range",
        "city": city if isinstance(city, str) else None,
        "start_date": start_date if isinstance(start_date, str) else None,
        "end_date": end_date if isinstance(end_date, str) else None,
        "timezone_name": None,
        "resolved_location_id": None,
        "request_status": "received",
        "error_code": None,
        "error_message": None,
        "response_summary": None,
        "provider_calls": 0,
        "duration_ms": None,
        "created_at": created_ts,
        "updated_at": created_ts,
    }
    tool_invocations.append(inv)
    _save("tool_invocations.json", tool_invocations)

    def _finish_fail(api_code, msg, error_code, error_message=None):
        duration_ms = int((time.time() - t0) * 1000)
        _update_inv(inv, tool_invocations, status="failed", error_code=error_code, error_message=error_message or msg, duration_ms=duration_ms)
        _save("tool_invocations.json", tool_invocations)
        return _err(api_code, msg, error_code=error_code)

    def _finish_success(payload, summary=None):
        duration_ms = int((time.time() - t0) * 1000)
        _update_inv(inv, tool_invocations, status="succeeded", response_summary=summary, duration_ms=duration_ms)
        _save("tool_invocations.json", tool_invocations)
        return payload

    # Validate client status
    if client.get("status") != "active":
        return _finish_fail("UNAUTHORIZED", "Client is not active.", "CLIENT_NOT_ACTIVE", "Client is not active; invocation blocked.")

    # Validate inputs
    if not isinstance(city, str) or not city.strip():
        return _finish_fail("VALIDATION_ERROR", "city must be a non-empty string.", "CITY_INVALID")
    sd = _parse_ymd(start_date)
    ed = _parse_ymd(end_date)
    if not sd or not ed:
        return _finish_fail("VALIDATION_ERROR", "start_date and end_date must be in YYYY-MM-DD format.", "INVALID_DATE_RANGE")
    if sd > ed:
        return _finish_fail("VALIDATION_ERROR", "start_date must be <= end_date.", "INVALID_DATE_RANGE")

    # NOTE: Do NOT enforce 31-day max here; audit requires relaxing stricter-than-acceptable checks.
    _update_inv(inv, tool_invocations, status="validated")
    _save("tool_invocations.json", tool_invocations)

    # Rate/quota limits after validation, before running
    lim = _enforce_limits(client, tool_invocations)
    if lim:
        api_code, msg, errc = lim
        return _finish_fail(api_code, msg, errc)

    _update_inv(inv, tool_invocations, status="running")
    _save("tool_invocations.json", tool_invocations)

    # Resolve / create location
    norm_city = _norm_city(city)
    loc, created = _find_or_create_resolved_location(norm_city, locations)
    inv["resolved_location_id"] = loc.get("id")
    _update_inv(inv, tool_invocations)  # persist resolved_location_id
    if created:
        _save("locations.json", locations)
        _save("tool_invocations.json", tool_invocations)
    else:
        _save("tool_invocations.json", tool_invocations)

    # Gather hourly rows in range, fetching/upserting missing/stale
    start_dt, end_excl = _hourly_bounds(sd, ed)

    # Index existing rows by hour for this location/provider
    provider = "open_meteo"
    by_hour = {}
    for r in weather_hourly:
        if not isinstance(r, dict):
            continue
        if r.get("location_id") != loc.get("id"):
            continue
        if r.get("source_provider") != provider:
            continue
        dt = _parse_hour(r.get("hour_start_utc"))
        if not dt:
            continue
        by_hour[dt] = r

    provider_calls = 0
    changed_any = False
    rows = []

    cur = start_dt
    while cur < end_excl:
        row = by_hour.get(cur)
        if row and row.get("ingest_status") in ("fresh", "stale") and not _is_stale(row, datetime.datetime.now(datetime.timezone.utc)):
            rows.append(row)
        else:
            ensured, calls, changed = _ensure_hour(loc.get("id"), cur, weather_hourly)
            provider_calls += calls
            changed_any = changed_any or changed
            # refresh index and append
            by_hour[cur] = ensured
            rows.append(ensured)
        cur += datetime.timedelta(hours=1)

    inv["provider_calls"] = int(provider_calls)
    _update_inv(inv, tool_invocations)
    _save("tool_invocations.json", tool_invocations)
    if changed_any:
        _save("weather_hourly.json", weather_hourly)

    # Sort by hour_start_utc ascending (stable)
    def _hour_key(r):
        dt = _parse_hour(r.get("hour_start_utc"))
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    rows_sorted = sorted(rows, key=_hour_key)

    # Build response: do not fabricate fields; return existing row dicts as stored.
    summary = f"{norm_city}: {len(rows_sorted)} hourly records from {start_date} to {end_date} (inclusive)."
    return _finish_success(
        {
            "city": norm_city,
            "location_id": loc.get("id"),
            "start_date": start_date,
            "end_date": end_date,
            "count": len(rows_sorted),
            "provider_calls": int(provider_calls),
            "rows": rows_sorted,
        },
        summary=summary,
    )

def get_current_datetime(timezone_name, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0208000" if __import__("os").path.isdir("./environment_mix/0208000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso_z(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(1000, 9999)}"

    def _pick_active_client(clients):
        for c in clients:
            if c.get("status") == "active":
                return c
        return None

    def _enforce_limits(client, invocations, now):
        client_id = client.get("id")
        rl = client.get("rate_limit_per_minute")
        dq = client.get("daily_quota")

        if not isinstance(rl, int) or not (1 <= rl <= 6000):
            return ("UNAUTHORIZED", "Client rate limit misconfigured", "CLIENT_MISCONFIGURED")
        if not isinstance(dq, int) or not (1 <= dq <= 1000000):
            return ("UNAUTHORIZED", "Client daily quota misconfigured", "CLIENT_MISCONFIGURED")

        window_start = now - datetime.timedelta(seconds=60)
        count_60s = 0
        for r in invocations:
            if r.get("client_id") != client_id:
                continue
            dt = _parse_iso_z(r.get("created_at"))
            if dt is None:
                continue
            if dt >= window_start and dt <= now:
                count_60s += 1
        if count_60s >= rl:
            return ("RATE_LIMIT", "Rate limit exceeded", "RATE_LIMITED")

        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        count_day = 0
        for r in invocations:
            if r.get("client_id") != client_id:
                continue
            dt = _parse_iso_z(r.get("created_at"))
            if dt is None:
                continue
            if dt >= day_start and dt <= now:
                count_day += 1
        if count_day >= dq:
            return ("QUOTA_EXCEEDED", "Daily quota exceeded", "DAILY_QUOTA_EXCEEDED")

        return None

    t0 = time.time()
    now = _now_utc()

    api_clients = _load("api_clients.json")
    tool_invocations = _load("tool_invocations.json")
    tz_cache = _load("timezone_clock_cache.json")

    client = _pick_active_client(api_clients)
    if not client:
        return _err("UNAUTHORIZED", "No active client available to execute tool")

    inv_id = _gen_id("inv")
    inv = {
        "id": inv_id,
        "client_id": client.get("id"),
        "tool_name": "get_current_datetime",
        "city": None,
        "start_date": None,
        "end_date": None,
        "timezone_name": timezone_name if isinstance(timezone_name, str) else None,
        "resolved_location_id": None,
        "request_status": "received",
        "error_code": None,
        "error_message": None,
        "response_summary": None,
        "provider_calls": 0,
        "duration_ms": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_invocations.append(inv)
    _save("tool_invocations.json", tool_invocations)

    def _fail(api_code, public_msg, error_code=None, error_message=None):
        inv["request_status"] = "failed"
        inv["error_code"] = error_code
        inv["error_message"] = error_message or public_msg
        inv["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        inv["updated_at"] = _iso(_now_utc())
        _save("tool_invocations.json", tool_invocations)
        return _err(api_code, public_msg, error_code=error_code)

    def _succeed(payload, summary):
        inv["request_status"] = "succeeded"
        inv["response_summary"] = summary
        inv["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        inv["updated_at"] = _iso(_now_utc())
        _save("tool_invocations.json", tool_invocations)
        return payload

    if client.get("status") != "active":
        return _fail("UNAUTHORIZED", "Client not permitted", error_code="CLIENT_NOT_ACTIVE")

    lim = _enforce_limits(client, tool_invocations[:-1], now)
    if lim:
        api_code, msg, ec = lim
        return _fail(api_code, msg, error_code=ec)

    if not isinstance(timezone_name, str) or not timezone_name.strip():
        # also upsert cache as invalid per business rule
        tz = "" if not isinstance(timezone_name, str) else timezone_name.strip()
        return _fail("VALIDATION_ERROR", "timezone_name must be a non-empty string", error_code="INVALID_TIMEZONE")

    tz_name = timezone_name.strip()
    inv["timezone_name"] = tz_name
    inv["request_status"] = "validated"
    inv["updated_at"] = _iso(_now_utc())
    _save("tool_invocations.json", tool_invocations)

    # Validate timezone (IANA or UTC)
    is_valid = False
    offset_minutes = None
    local_dt = None
    try:
        from zoneinfo import ZoneInfo
        if tz_name == "UTC":
            is_valid = True
            zi = datetime.timezone.utc
            local_dt = now.astimezone(zi)
            offset_minutes = 0
        else:
            zi = ZoneInfo(tz_name)
            local_dt = now.astimezone(zi)
            is_valid = True
            off = local_dt.utcoffset()
            offset_minutes = int(off.total_seconds() // 60) if off is not None else None
    except Exception:
        is_valid = False
        local_dt = None
        offset_minutes = None

    # Upsert timezone_clock_cache
    existing = None
    for r in tz_cache:
        if r.get("timezone_name") == tz_name:
            existing = r
            break

    ts_now = _iso(_now_utc())
    if existing:
        existing["is_valid"] = bool(is_valid)
        existing["last_offset_minutes"] = offset_minutes
        existing["last_computed_at"] = ts_now
        existing["updated_at"] = ts_now
    else:
        tz_cache.append({
            "id": _gen_id("tz"),
            "timezone_name": tz_name,
            "is_valid": bool(is_valid),
            "last_offset_minutes": offset_minutes,
            "last_computed_at": ts_now,
            "created_at": ts_now,
            "updated_at": ts_now,
        })
    _save("timezone_clock_cache.json", tz_cache)

    if not is_valid:
        return _fail("VALIDATION_ERROR", "timezone_name is not a valid IANA timezone identifier", error_code="INVALID_TIMEZONE")

    inv["request_status"] = "running"
    inv["updated_at"] = _iso(_now_utc())
    _save("tool_invocations.json", tool_invocations)

    payload = {
        "timezone_name": tz_name,
        "datetime": local_dt.isoformat(),
        "utc_datetime": now.isoformat().replace("+00:00", "Z"),
        "utc_offset_minutes": offset_minutes,
    }
    summary = f"Current datetime in {tz_name}: {payload['datetime']}"
    return _succeed(payload, summary)

def resolve_city(api_key, city, country_code=None, admin_region=None, prefer_timezone_name=None, max_candidates=None, **_extra):
    import json, os, datetime, time, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0208000" if __import__("os").path.isdir("./environment_mix/0208000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso_z(s):
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _norm_city(c):
        c = c.strip()
        c = re.sub(r"\s+", " ", c)
        return c.title()

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(100000, 999999)}"

    def _inv_transition_ok(frm, to):
        allowed = {
            "received": {"validated", "failed"},
            "validated": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        return frm in allowed and to in allowed[frm]

    def _new_invocation(client_id):
        ts = _iso(now)
        return {
            "id": _gen_id("wcs_inv"),
            "client_id": client_id,
            "tool_name": "resolve_city",
            "city": city if isinstance(city, str) else None,
            "start_date": None,
            "end_date": None,
            "timezone_name": None,
            "resolved_location_id": None,
            "request_status": "received",
            "error_code": None,
            "error_message": None,
            "response_summary": None,
            "provider_calls": 0,
            "duration_ms": None,
            "created_at": ts,
            "updated_at": ts,
        }

    def _set_status(inv_row, new_status, error_code=None, error_message=None, response_summary=None):
        cur = inv_row.get("request_status")
        if cur == new_status:
            return True
        if not _inv_transition_ok(cur, new_status):
            inv_row["request_status"] = "failed"
            inv_row["error_code"] = "INVALID_TRANSITION"
            inv_row["error_message"] = f"Illegal transition {cur}->{new_status}"
            inv_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            return False
        inv_row["request_status"] = new_status
        if error_code is not None:
            inv_row["error_code"] = error_code
        if error_message is not None:
            inv_row["error_message"] = error_message
        if response_summary is not None:
            inv_row["response_summary"] = response_summary
        inv_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        return True

    def _auth_client(api_clients, api_key_value):
        # Authenticate against client-visible value: allow id match, api_key field (if present), or name for dev.
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        key = api_key_value.strip()
        for c in api_clients:
            if c.get("id") == key:
                return c
        for c in api_clients:
            if c.get("api_key") == key:
                return c
        for c in api_clients:
            if c.get("name") == key:
                return c
        # Some stores use api_key_hash as client-visible token (already a string like "sha256$..."); allow direct equality
        for c in api_clients:
            if c.get("api_key_hash") == key:
                return c
        return None

    def _count_usage(invocations, client_id, now_dt):
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day, tzinfo=datetime.timezone.utc)
        day_end = day_start + datetime.timedelta(days=1)
        c60 = 0
        cday = 0
        for r in invocations:
            if r.get("client_id") != client_id:
                continue
            dt = _parse_iso_z(r.get("created_at"))
            if not dt:
                continue
            if dt >= window_start:
                c60 += 1
            if day_start <= dt < day_end:
                cday += 1
        return c60, cday

    def _valid_country_code(cc):
        if cc is None:
            return True
        return isinstance(cc, str) and len(cc) == 2 and cc.isalpha()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(city, str) or not city.strip():
        return _err("VALIDATION_ERROR", "city must be a non-empty string")
    if not _valid_country_code(country_code):
        return _err("VALIDATION_ERROR", "country_code must be a 2-letter ISO code when provided")
    if admin_region is not None and not isinstance(admin_region, str):
        return _err("VALIDATION_ERROR", "admin_region must be a string when provided")
    if prefer_timezone_name is not None and not isinstance(prefer_timezone_name, str):
        return _err("VALIDATION_ERROR", "prefer_timezone_name must be a string when provided")
    if max_candidates is None:
        max_candidates = 5
    if not isinstance(max_candidates, int) or not (1 <= max_candidates <= 25):
        return _err("VALIDATION_ERROR", "max_candidates must be an integer between 1 and 25")

    api_clients = _load("api_clients.json")
    client = _auth_client(api_clients, api_key)
    if not client or client.get("status") == "revoked":
        return _err("UNAUTHORIZED", "Invalid API key")

    invocations = _load("tool_invocations.json")
    inv_row = _new_invocation(client.get("id"))
    invocations.append(inv_row)
    _save("tool_invocations.json", invocations)

    try:
        if client.get("status") != "active":
            _set_status(inv_row, "failed", error_code="CLIENT_NOT_ACTIVE", error_message="Client is not active; invocation blocked.")
            inv_row["duration_ms"] = int((time.time() - t0) * 1000)
            _save("tool_invocations.json", invocations)
            return _err("UNAUTHORIZED", "Client not active", error_code="CLIENT_NOT_ACTIVE")

        _set_status(inv_row, "validated")
        _save("tool_invocations.json", invocations)

        c60, cday = _count_usage(invocations, client.get("id"), now)
        rl = client.get("rate_limit_per_minute")
        dq = client.get("daily_quota")
        if isinstance(rl, int) and c60 > rl:
            _set_status(inv_row, "failed", error_code="RATE_LIMITED", error_message=f"Rate limit exceeded for client (limit={rl}/min).")
            inv_row["duration_ms"] = int((time.time() - t0) * 1000)
            _save("tool_invocations.json", invocations)
            return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED")
        if isinstance(dq, int) and cday > dq:
            _set_status(inv_row, "failed", error_code="DAILY_QUOTA_EXCEEDED", error_message=f"Daily quota exceeded for client (quota={dq}/day).")
            inv_row["duration_ms"] = int((time.time() - t0) * 1000)
            _save("tool_invocations.json", invocations)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", error_code="DAILY_QUOTA_EXCEEDED")

        _set_status(inv_row, "running")
        _save("tool_invocations.json", invocations)

        locations = _load("locations.json")
        ncity = _norm_city(city)

        # Candidate selection
        candidates = [r for r in locations if (r.get("english_city_name") or "").lower() == ncity.lower()]
        if country_code:
            candidates = [r for r in candidates if (r.get("country_code") or "").upper() == country_code.upper()]
        if admin_region:
            candidates = [r for r in candidates if (r.get("admin_region") or "").lower() == admin_region.lower()]

        # Tie-break with prefer_timezone_name if supplied
        if prefer_timezone_name:
            tz_matches = [r for r in candidates if (r.get("timezone_name") or "") == prefer_timezone_name]
            if tz_matches:
                candidates = tz_matches

        # Pick best
        resolved = [r for r in candidates if r.get("resolution_status") == "resolved"]
        if resolved:
            resolved.sort(key=lambda r: r.get("updated_at") or "", reverse=True)
            best = resolved[0]
            inv_row["resolved_location_id"] = best.get("id")
            summary = f"Resolved {ncity} to {best.get('id')}."
            _set_status(inv_row, "succeeded", response_summary=summary)
            inv_row["duration_ms"] = int((time.time() - t0) * 1000)
            _save("tool_invocations.json", invocations)
            return {"city_normalized": ncity, "resolution_status": "resolved", "location": best}

        # If we have non-resolved candidates, return them as ambiguous/failed depending on their statuses
        if candidates:
            candidates.sort(key=lambda r: r.get("updated_at") or "", reverse=True)
            out = candidates[:max_candidates]
            # Determine overall
            any_amb = any(r.get("resolution_status") == "ambiguous" for r in out)
            overall = "ambiguous" if any_amb else out[0].get("resolution_status") or "ambiguous"
            inv_row["resolved_location_id"] = out[0].get("id")
            summary = f"{len(out)} candidate locations for {ncity}."
            _set_status(inv_row, "succeeded", response_summary=summary)
            inv_row["duration_ms"] = int((time.time() - t0) * 1000)
            _save("tool_invocations.json", invocations)
            return {"city_normalized": ncity, "resolution_status": overall, "candidates": out, "meta": {"count": len(out)}}

        # No candidates: create a new resolved location (offline), honoring constraints
        ts = _iso(datetime.datetime.now(datetime.timezone.utc))
        new_loc = {
            "id": _gen_id("wcs_loc"),
            "english_city_name": ncity,
