    fdt = _parse_iso_z(from_utc)
    if fdt == "BAD":
        return _err("VALIDATION_ERROR", "from_utc must be an ISO-8601 UTC timestamp when provided")
    tdt = _parse_iso_z(to_utc)
    if tdt == "BAD":
        return _err("VALIDATION_ERROR", "to_utc must be an ISO-8601 UTC timestamp when provided")
    if fdt and tdt and fdt > tdt:
        return _err("VALIDATION_ERROR", "from_utc must be <= to_utc")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or not (1 <= page_size <= 200):
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    api_clients = _load("api_clients.json")
    client = _auth_client(api_clients, api_key)
    if not client or client.get("status") == "revoked":
        return _err("UNAUTHORIZED", "Invalid API key")

    invocations_log = _load("tool_invocations.json")
    inv_row = _new_invocation(client.get("id"))
    invocations_log.append(inv_row)
    _save("tool_invocations.json", invocations_log)

    try:
        if client.get("status") != "active":
            _set_status(inv_row, "failed", error_code="CLIENT_NOT_ACTIVE", error_message="Client is not active; invocation blocked.")
            inv_row["duration_ms"] = int((time.time() - t0) * 1000)
            _save("tool_invocations.json", invocations_log)
            return _err("UNAUTHORIZED", "Client not active", error_code="CLIENT_NOT_ACTIVE")

        _set_status(inv_row, "validated")
        _save("tool_invocations.json", invocations_log)

        _set_status(inv_row, "running")
        _save("tool_invocations.json", invocations_log)

        rows = [r for r in invocations_log if r.get("client_id") == client.get("id")]
        if tool_name:
            rows = [r for r in rows if r.get("tool_name") == tool_name]
        if request_status:
            rows = [r for r in rows if r.get("request_status") == request_status]
        if fdt:
            rows = [r for r in rows if (_parse_iso_z(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) >= fdt]
        if tdt:
            rows = [r for r in rows if (_parse_iso_z(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)) < tdt]

        rows.sort(key=lambda r: r.get("created_at") or "", reverse=True)

        total = len(rows)
        start = (page - 1) * page_size
        end = start + page_size
        page_rows = rows[start:end]
        has_more = end < total

        _set_status(inv_row, "succeeded", response_summary=f"Returned {len(page_rows)} tool invocations.")
        inv_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_invocations.json", invocations_log)

        return {"invocations": page_rows, "meta": {"page": page, "page_size": page_size, "total": total, "has_more": has_more}}
    except Exception as e:
        invocations2 = _load("tool_invocations.json")
        inv_row2 = next((r for r in invocations2 if r.get("id") == inv_row.get("id")), inv_row)
        _set_status(inv_row2, "failed", error_code="INTERNAL_ERROR", error_message=str(e))
        inv_row2["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_invocations.json", invocations2)
        return _err("CONFLICT", "Internal error", error_code="INTERNAL_ERROR")

def get_auth_context(api_key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0208000" if __import__("os").path.isdir("./environment_mix/0208000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso_z(s):
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _auth_client(api_clients, api_key_value):
        # Must authenticate against client-visible value or id; NEVER hash compare.
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        key = api_key_value.strip()
        for c in api_clients:
            if c.get("id") == key:
                return c
        for c in api_clients:
            if c.get("api_key") == key:
                return c
        for c in api_clients:
            if c.get("name") == key:
                return c
        # Allow direct match to stored api_key_hash string if that string is what clients send (e.g. "sha256$...")
        for c in api_clients:
            if c.get("api_key_hash") == key:
                return c
        return None

    def _count_usage(invocations, client_id, now_dt):
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day, tzinfo=datetime.timezone.utc)
        day_end = day_start + datetime.timedelta(days=1)
        c60 = 0
        cday = 0
        for r in invocations:
            if r.get("client_id") != client_id:
                continue
            dt = _parse_iso_z(r.get("created_at"))
            if not dt:
                continue
            if dt >= window_start:
                c60 += 1
            if day_start <= dt < day_end:
                cday += 1
        return c60, cday

    def _inv_transition_ok(frm, to):
        allowed = {
            "received": {"validated", "failed"},
            "validated": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        return frm in allowed and to in allowed[frm]

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.urandom(3).hex()}"

    def _new_invocation(client_id):
        ts = _iso(now)
        return {
            "id": _gen_id("wcs_inv"),
            "client_id": client_id,
            "tool_name": "get_current_datetime",  # closest enum tool used to log this read
            "city": None,
            "start_date": None,
            "end_date": None,
            "timezone_name": None,
            "resolved_location_id": None,
            "request_status": "received",
            "error_code": None,
            "error_message": None,
            "response_summary": None,
            "provider_calls": 0,
            "duration_ms": None,
            "created_at": ts,
            "updated_at": ts,
        }

    def _set_status(inv_row, new_status, error_code=None, error_message=None, response_summary=None):
        cur = inv_row.get("request_status")
        if cur == new_status:
            return True
        if not _inv_transition_ok(cur, new_status):
            inv_row["request_status"] = "failed"
            inv_row["error_code"] = "INVALID_TRANSITION"
            inv_row["error_message"] = f"Illegal transition {cur}->{new_status}"
            inv_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            return False
        inv_row["request_status"] = new_status
        if error_code is not None:
            inv_row["error_code"] = error_code
        if error_message is not None:
            inv_row["error_message"] = error_message
        if response_summary is not None:
            inv_row["response_summary"] = response_summary
        inv_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        return True

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_clients = _load("api_clients.json")
    client = _auth_client(api_clients, api_key)
    if not client or client.get("status") == "revoked":
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    invocations = _load("tool_invocations.json")
    inv_row = _new_invocation(client.get("id"))
    invocations.append(inv_row)
    _save("tool_invocations.json", invocations)

    try:
        # get_auth_context itself should be callable even if suspended? spec says "revoked" refused; keep active check informational.
        _set_status(inv_row, "validated")
        _set_status(inv_row, "running")
        _save("tool_invocations.json", invocations)

        c60, cday = _count_usage(invocations, client.get("id"), now)
        rate_limit = client.get("rate_limit_per_minute")
        daily_quota = client.get("daily_quota")

        body = {
            "client": {
                "id": client.get("id"),
                "name": client.get("name"),
                "status": client.get("status"),
                "rate_limit_per_minute": rate_limit,
                "daily_quota": daily_quota,
                "created_at": client.get("created_at"),
                "updated_at": client.get("updated_at"),
            },
            "usage": {
                "rolling_minute_count": c60,
                "daily_count": cday,
            },
            "server_time_utc": _iso(now),
        }

        _set_status(inv_row, "succeeded", response_summary="Returned auth context.")
        inv_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_invocations.json", invocations)
        return body
    except Exception as e:
        invocations2 = _load("tool_invocations.json")
        inv_row2 = next((r for r in invocations2 if r.get("id") == inv_row.get("id")), inv_row)
        _set_status(inv_row2, "failed", error_code="INTERNAL_ERROR", error_message=str(e))
        inv_row2["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_invocations.json", invocations2)
        return _err("CONFLICT", "Internal error", error_code="INTERNAL_ERROR")

def update_location_resolution_status(api_key, location_id, resolution_status, provider=None, provider_location_ref=None, latitude=None, longitude=None, timezone_name=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0208000" if __import__("os").path.isdir("./environment_mix/0208000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00").astimezone(datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # Validate required inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(location_id, str) or not location_id.strip():
        return _err("VALIDATION_ERROR", "location_id must be a non-empty string")
    if resolution_status not in ("resolved", "ambiguous", "failed"):
        return _err("VALIDATION_ERROR", "resolution_status must be one of: resolved, ambiguous, failed")
    if provider is not None and (not isinstance(provider, str) or not provider.strip()):
        return _err("VALIDATION_ERROR", "provider must be a non-empty string when provided")
    if provider_location_ref is not None and not isinstance(provider_location_ref, str):
        return _err("VALIDATION_ERROR", "provider_location_ref must be a string when provided")
    if latitude is not None and not isinstance(latitude, (int, float)):
        return _err("VALIDATION_ERROR", "latitude must be a number when provided")
    if longitude is not None and not isinstance(longitude, (int, float)):
        return _err("VALIDATION_ERROR", "longitude must be a number when provided")
    if timezone_name is not None and (not isinstance(timezone_name, str) or not timezone_name.strip()):
        return _err("VALIDATION_ERROR", "timezone_name must be a non-empty string when provided")

    t0 = time.time()
    now = _now_utc()

    api_clients = _load("api_clients.json")
    locations = _load("locations.json")
    tool_invocations = _load("tool_invocations.json")

    # Authenticate: api_key may match client-visible value or id.
    # Because only api_key_hash exists, treat api_key_hash as the client-visible credential value in this datastore.
    client = None
    for c in api_clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            client = c
            break
    if client is None:
        # No invocation row required for this tool (tool_invocations.tool_name enum doesn't include it)
        return _err("UNAUTHORIZED", "Invalid API key")

    # Enforce client active
    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active", error_code="CLIENT_NOT_ACTIVE")

    # Rate limit + daily quota using tool_invocations (includes only known tools, but still used for enforcement)
    client_id = client.get("id")
    rate_limit = client.get("rate_limit_per_minute")
    daily_quota = client.get("daily_quota")
    if not isinstance(rate_limit, int) or not (1 <= rate_limit <= 6000):
        return _err("VALIDATION_ERROR", "Client rate_limit_per_minute is invalid in datastore")
    if not isinstance(daily_quota, int) or not (1 <= daily_quota <= 1000000):
        return _err("VALIDATION_ERROR", "Client daily_quota is invalid in datastore")

    window_start = now - datetime.timedelta(seconds=60)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    recent = 0
    today = 0
    for inv in tool_invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("client_id") != client_id:
            continue
        created = _parse_dt(inv.get("created_at"))
        if created is None:
            continue
        if created >= window_start:
            recent += 1
        if created >= day_start and created <= now + datetime.timedelta(days=1):
            today += 1

    if recent >= rate_limit:
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="RATE_LIMITED")
    if today >= daily_quota:
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", error_code="DAILY_QUOTA_EXCEEDED")

    # Find location
    loc = None
    loc_idx = None
    for i, r in enumerate(locations):
        if isinstance(r, dict) and r.get("id") == location_id:
            loc = r
            loc_idx = i
            break
    if loc is None:
        return _err("NOT_FOUND", "Location not found", location_id=location_id)

    # Validate lifecycle transition
    current = loc.get("resolution_status")
    allowed = {
        "failed": {"resolved", "ambiguous"},
        "ambiguous": {"resolved", "failed"},
        "resolved": {"ambiguous"},
    }
    if current not in allowed:
        return _err("VALIDATION_ERROR", "Location has invalid resolution_status in datastore", current=current)
    if resolution_status == current:
        # Idempotent: still update optional fields if provided, but only if they don't violate constraints.
        transition_ok = True
    else:
        transition_ok = resolution_status in allowed.get(current, set())

    if not transition_ok:
        return _err(
            "CONFLICT",
            "Requested transition is not permitted from current state",
            current_resolution_status=current,
            requested_resolution_status=resolution_status,
        )

    # Field-level validation for constraints
    if latitude is not None and not (-90 <= float(latitude) <= 90):
        return _err("VALIDATION_ERROR", "latitude must be between -90 and 90")
    if longitude is not None and not (-180 <= float(longitude) <= 180):
        return _err("VALIDATION_ERROR", "longitude must be between -180 and 180")
    if timezone_name is not None:
        # lightweight IANA format check (also used elsewhere in schema)
        # Accept "UTC" or "Area/City" (and deeper paths)
        if timezone_name != "UTC" and not re.match(r"^[A-Za-z][A-Za-z0-9_\-+]*\/[A-Za-z0-9_\-+]+(?:\/[A-Za-z0-9_\-+]+)*$", timezone_name):
            return _err("VALIDATION_ERROR", "timezone_name must be a valid IANA identifier or 'UTC'")

    # Unique(provider, provider_location_ref) where provider_location_ref is not null
    if provider_location_ref is not None:
        prov = provider if provider is not None else loc.get("provider")
        if prov is None or not isinstance(prov, str) or not prov.strip():
            return _err("VALIDATION_ERROR", "provider must be set when provider_location_ref is provided")
        for r in locations:
            if not isinstance(r, dict):
                continue
            if r.get("id") == location_id:
                continue
            if r.get("provider") == prov and r.get("provider_location_ref") == provider_location_ref:
                return _err("CONFLICT", "provider_location_ref already exists for provider", provider=prov, provider_location_ref=provider_location_ref)

    # When moving to 'resolved', latitude/longitude should be present to satisfy non-null constraints.
    # If not provided, allow only if already present in row.
    if resolution_status == "resolved":
        if latitude is None and not isinstance(loc.get("latitude"), (int, float)):
            return _err("VALIDATION_ERROR", "latitude must be provided when moving to 'resolved' if not already stored")
        if longitude is None and not isinstance(loc.get("longitude"), (int, float)):
            return _err("VALIDATION_ERROR", "longitude must be provided when moving to 'resolved' if not already stored")

    # Apply updates
    updated = dict(loc)
    updated["resolution_status"] = resolution_status

    if provider is not None:
        updated["provider"] = provider
    if provider_location_ref is not None:
        updated["provider_location_ref"] = provider_location_ref
    if latitude is not None:
        updated["latitude"] = float(latitude)
    if longitude is not None:
        updated["longitude"] = float(longitude)
    if timezone_name is not None:
        updated["timezone_name"] = timezone_name

    updated["updated_at"] = _iso(now)

    # Persist
    locations[loc_idx] = updated
    try:
        _save("locations.json", locations)
    except Exception as e:
        return _err("CONFLICT", "Failed to persist location update", detail=str(e))

    duration_ms = int((time.time() - t0) * 1000)

    # Return updated location (no tool_invocations row for this tool due to enum restriction in schema)
    return {
        "location": updated,
        "meta": {
            "authenticated_client_id": client_id,
            "duration_ms": duration_ms,
        },
    }
